  },
  "Altruistic_Catalysts": {
    "is_used": "No",
    "explanation": "The text does not portray challengers, rebels, martyrs, or underdogs driving systemic change or sacrificing themselves; it emphasizes information dissemination rather than radical activism or personal sacrifice."
