    "is_used": "No",
    "explanation": "The passage emphasizes accuracy and reliability and contains no suggestions of secrecy, betrayal, manipulation, misinformation, or covert activity."
  },
  "Institutional_Toxins": {
    "is_used": "No",
    "explanation": "There is no depiction of corruption, incompetence, or institutional failure; the WHO is presented positively and competently."
  },
  "Marginalized_Sufferers": {
