  },
  "Altruistic_Catalysts": {
    "is_used": "No",
    "explanation": "The passage does not frame anyone as challenging the status quo, sacrificing for a cause, or an underdog fighting larger forces; language focuses on public-health response rather than protest or heroic sacrifice."
