  },
  "Altruistic_Catalysts": {
    "is_used": "No",
    "explanation": "The passage notes that some staff stayed on site, but it does not emphasize sacrifice, revolt, or inspirational struggle against a larger oppressive force that would indicate a Rebel, Martyr, or Underdog framing."
